"""Run the native Logfire CLI installed in this wheel."""

from __future__ import annotations

import importlib.metadata
import os
import sys
from pathlib import Path


def main() -> None:
    """Replace this process with the bundled, provenance-verified CLI."""
    binary = Path(__file__).with_name("bin") / ("logfire.exe" if os.name == "nt" else "logfire")
    os.environ["LOGFIRE_CLI_DISTRIBUTION"] = "pypi"
    os.environ["LOGFIRE_CLI_COMMAND_NAME"] = "logfire-cli"
    # Recognize uv's versioned archive environments; unknown layouts use the bare command.
    if os.environ.get("UV") and any(part.startswith("archive-v") and part[9:].isdigit() for part in Path(sys.prefix).parts):
        os.environ["LOGFIRE_CLI_RUNNER"] = "uvx"
    else:
        os.environ.pop("LOGFIRE_CLI_RUNNER", None)
    try:
        os.environ["LOGFIRE_CLI_SDK_VERSION"] = importlib.metadata.version("logfire-sdk")
    except importlib.metadata.PackageNotFoundError:
        os.environ.pop("LOGFIRE_CLI_SDK_VERSION", None)
    os.execv(binary, [str(binary), *sys.argv[1:]])
